using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools the research agent can invoke during its agentic loop.
/// </summary>
public sealed class ResearchTools
{
    private readonly HttpClient _httpClient;
    private readonly List<NoteEntry> _notes = [];

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            return ParseDuckDuckGoResults(html);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"  ⚠️  Search failed: {ex.Message}");
            return [new SearchResult($"Search for: {query}", "", "Search unavailable. Please summarize based on general knowledge.")];
        }
    }

    [Description("Save a research note with a topic label and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short label or topic for the note")] string topic,
        [Description("The content of the note")] string content)
    {
        var entry = new NoteEntry(topic, content, DateTime.UtcNow);
        _notes.Add(entry);
        Console.WriteLine($"  📝 Note saved: \"{topic}\"");
        return $"Note saved: \"{topic}\" ({content.Length} chars)";
    }

    [Description("Retrieve all previously saved research notes.")]
    public IReadOnlyList<NoteEntry> GetNotes()
    {
        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return _notes;
    }

    private static List<SearchResult> ParseDuckDuckGoResults(string html)
    {
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        // Parse result blocks from DuckDuckGo HTML response
        const string resultMarker = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        int pos = 0;
        while (results.Count < 5)
        {
            int titleStart = html.IndexOf(resultMarker, pos, StringComparison.Ordinal);
            if (titleStart < 0) break;

            string title = ExtractTagContent(html, titleStart);
            string url = ExtractHref(html, titleStart);

            int snippetStart = html.IndexOf(snippetMarker, titleStart, StringComparison.Ordinal);
            string snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(
                    StripHtml(title).Trim(),
                    url,
                    StripHtml(snippet).Trim()));
            }

            pos = snippetStart >= 0 ? snippetStart + 1 : titleStart + resultMarker.Length;
        }

        if (results.Count == 0)
        {
            results.Add(new SearchResult("No results found", "", "The search did not return any results."));
        }

        return results;
    }

    private static string ExtractTagContent(string html, int markerPos)
    {
        int tagClose = html.IndexOf('>', markerPos);
        if (tagClose < 0) return "";

        int contentStart = tagClose + 1;
        int contentEnd = html.IndexOf('<', contentStart);
        if (contentEnd < 0) return "";

        // Grab more content that might span inner tags
        int depth = 1;
        int i = contentStart;
        while (i < html.Length && depth > 0)
        {
            if (html[i] == '<')
            {
                if (i + 1 < html.Length && html[i + 1] == '/') depth--;
                else if (i + 1 < html.Length && html[i + 1] != '!' && html[i + 1] != 'b') depth++;
            }
            i++;
        }

        return html[contentStart..Math.Min(i, html.Length)];
    }

    private static string ExtractHref(string html, int pos)
    {
        int hrefStart = html.LastIndexOf("href=\"", pos, Math.Min(pos, 200), StringComparison.Ordinal);
        if (hrefStart < 0)
        {
            hrefStart = html.IndexOf("href=\"", pos, StringComparison.Ordinal);
        }
        if (hrefStart < 0) return "";

        int urlStart = hrefStart + 6;
        int urlEnd = html.IndexOf('"', urlStart);
        if (urlEnd < 0) return "";

        var rawUrl = html[urlStart..urlEnd];

        // DuckDuckGo wraps URLs in a redirect; extract the actual URL
        if (rawUrl.Contains("uddg=", StringComparison.Ordinal))
        {
            int paramStart = rawUrl.IndexOf("uddg=", StringComparison.Ordinal) + 5;
            int paramEnd = rawUrl.IndexOf('&', paramStart);
            var encoded = paramEnd >= 0 ? rawUrl[paramStart..paramEnd] : rawUrl[paramStart..];
            return Uri.UnescapeDataString(encoded);
        }

        return rawUrl;
    }

    private static string StripHtml(string html)
    {
        var chars = new char[html.Length];
        int j = 0;
        bool inTag = false;
        foreach (char c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) chars[j++] = c;
        }
        return new string(chars, 0, j);
    }
}

public sealed record SearchResult(string Title, string Url, string Snippet);

public sealed record NoteEntry(string Topic, string Content, DateTime Timestamp);

