using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run the research agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the chat client via MEAI abstraction ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Set up tools ---
using var httpClient = new HttpClient();
var tools = new ResearchTools(httpClient);

var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.SearchWebAsync),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Create the agent ---
const string instructions = """
    You are a research agent. Your goal is to thoroughly research a topic provided by the user.

    Follow this workflow:
    1. Break the topic into 2-3 key sub-questions.
    2. Use the SearchWeb tool to search for information on each sub-question.
    3. Use the SaveNote tool to record important findings as you go — include sources when available.
    4. After gathering enough information, use GetNotes to review your collected research.
    5. Provide a comprehensive summary of your findings, organized with clear headings.

    Be thorough but concise. Cite sources where possible. If search results are limited,
    supplement with your general knowledge and note what is from search vs. general knowledge.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools",
    tools: aiTools);

// --- Get the topic from the user ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent           ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "";
}

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"📚 Researching: {topic}");
Console.WriteLine(new string('─', 50));

// --- Run the agent ---
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

// --- Display results ---
Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));
Console.WriteLine();

var lastMessage = response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant);
Console.WriteLine(lastMessage?.Text ?? "No summary generated.");

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"📝 Notes collected: {tools.Notes.Count}");

foreach (var note in tools.Notes)
{
    Console.WriteLine($"  • [{note.Topic}] {note.Content[..Math.Min(note.Content.Length, 80)]}...");
}

Console.WriteLine();
Console.WriteLine("✅ Research complete.");

